package io.github.jimbozoomer.jugcraft.test;
import io.github.jimbozoomer.jugcraft.finance.*;
import io.github.jimbozoomer.jugcraft.boardgames.*;
import java.util.*;
import net.fabricmc.fabric.api.gametest.v1.GameTest;
import net.minecraft.gametest.framework.GameTestHelper;
import net.minecraft.core.BlockPos;
import com.mojang.serialization.JsonOps;
public final class BoardWagerTests {
 private static FinanceBook book(FinanceBook.MapWallet w,UUID a,UUID b){var f=new FinanceBook();f.useWallet(w);f.account(a,"White");f.account(b,"Black");return f;}
 @GameTest(maxTicks=40) public void potConservationAndExactlyOnceAcrossSave(GameTestHelper h){var a=UUID.randomUUID();var b=UUID.randomUUID();var w=new FinanceBook.MapWallet();w.add(a,100);w.add(b,100);var f=book(w,a,b);var l=new Ledger(f);var e=l.boardWagers;
  h.assertTrue(e.fund(f,"table","round1",a,b,5,0,0).ok(),"Both stakes accepted");h.assertTrue(w.balance(a)==95&&w.balance(b)==95&&f.escrow()==10,"Pot fully funded");h.assertTrue(!e.fund(f,"table","round1",a,b,5,0,0).ok(),"No repeated debit");
  var encoded=Ledger.CODEC.encodeStart(JsonOps.INSTANCE,l).getOrThrow();var restored=Ledger.CODEC.parse(JsonOps.INSTANCE,encoded).getOrThrow();restored.book().useWallet(w);
  h.assertTrue(restored.boardWagers.open("table","round1"),"Open escrow survives ledger reload");h.assertTrue(restored.boardWagers.settle(restored.book(),"table","round1",0),"Win paid");h.assertTrue(w.balance(a)==105&&w.balance(b)==95&&restored.book().escrow()==0,"Only combined pot paid");
  var again=Ledger.CODEC.parse(JsonOps.INSTANCE,Ledger.CODEC.encodeStart(JsonOps.INSTANCE,restored).getOrThrow()).getOrThrow();again.book().useWallet(w);h.assertTrue(!again.boardWagers.settle(again.book(),"table","round1",0)&&w.balance(a)==105,"Saved receipt prevents repeated payout");h.assertTrue(again.boardWagers.fund(again.book(),"table","round2",a,b,10,0,0).ok(),"Fresh round may fund");h.assertTrue(!again.boardWagers.settle(again.book(),"table","round1",1),"Stale round cannot consume new pot");again.boardWagers.settle(again.book(),"table","round2",-1);h.assertTrue(w.balance(a)==105&&w.balance(b)==95&&again.book().escrow()==0,"Draw refunds both");h.succeed();
 }
 @GameTest(maxTicks=40) public void failedFundingExpiryAndCapacity(GameTestHelper h){var a=UUID.randomUUID();var b=UUID.randomUUID();var w=new FinanceBook.MapWallet();w.add(a,100);var f=book(w,a,b);var e=new BoardWagers();h.assertTrue(!e.fund(f,"k","1",a,b,5,0,0).ok()&&w.balance(a)==100&&f.escrow()==0,"Insufficient second wallet rolls first back");h.assertTrue(!e.fund(f,"k","1",a,a,5,0,0).ok()&&!e.fund(f,"k","1",a,b,999,0,0).ok(),"Same identity and out-of-range stakes rejected");w.add(b,100);e.fund(f,"k","2",a,b,5,0,0);h.assertTrue(!e.expire(f,BoardWagers.EXPIRY_MILLIS-1)&&e.expire(f,BoardWagers.EXPIRY_MILLIS),"Bounded expiry refunds");h.assertTrue(w.balance(a)==100&&w.balance(b)==100,"Expiry preserves balances");e.fund(f,"k","3",a,b,5,0,0);
  f.useWallet(new FinanceBook.Wallet(){public long balance(UUID id){return w.balance(id);}public boolean take(UUID id,long n){return w.take(id,n);}public boolean add(UUID id,long n){return false;}public Map<UUID,Long> all(){return w.all();}});e.settle(f,"k","3",0);h.assertTrue(f.pendingCredits().getOrDefault(a,0L)==10&&f.escrow()==0,"Full wallet preserves winnings as Exchange credit");h.succeed();
 }
 @GameTest(maxTicks=40) public void proposalsCannotChargeWithoutConsent(GameTestHelper h){var pos=new BlockPos(2,2,2);h.setBlock(pos,BoardGames.CHESS.defaultBlockState());var t=h.getBlockEntity(pos,TableEntity.class);var a=UUID.randomUUID();var b=UUID.randomUUID();t.change(a,"White",0,0,0,0);t.change(b,"Black",0,0,0,0);
  h.assertTrue(t.change(a,"White",8,0,0,0)&&t.stake==1&&!t.active(),"Proposal blocks moves");h.assertTrue(!t.change(a,"White",1,12,28,0),"Cannot move before stake accepted");t.change(a,"White",9,0,0,0);h.assertTrue(t.agreed[0]&&t.betId.isEmpty(),"One consent cannot charge");t.change(b,"Black",8,0,0,0);h.assertTrue(t.stake==5&&!t.agreed[0]&&!t.agreed[1],"New stake clears both consents");t.change(b,"Black",10,0,0,0);h.assertTrue(t.stake==0&&t.active(),"Either player may decline to free play");h.succeed();
 }
 @GameTest(maxTicks=40) public void removalRefundsButUnloadDoesNot(GameTestHelper h){var pos=new BlockPos(2,2,2);h.setBlock(pos,BoardGames.CHECKERS.defaultBlockState());var t=h.getBlockEntity(pos,TableEntity.class);var a=UUID.randomUUID();var b=UUID.randomUUID();var ledger=Ledger.get(h.getLevel().getServer());var f=ledger.book();f.account(a,"White");f.account(b,"Black");io.github.jimbozoomer.jugcraft.town.Jugs.add(h.getLevel().getServer(),a,100);io.github.jimbozoomer.jugcraft.town.Jugs.add(h.getLevel().getServer(),b,100);t.change(a,"White",0,0,0,0);t.change(b,"Black",0,0,0,0);t.stake=5;t.betId=UUID.randomUUID().toString();h.assertTrue(ledger.boardWagers.fund(f,t.wagerKey(),t.betId,a,b,5,0,System.currentTimeMillis()).ok(),"Fund removal fixture");t.setRemoved();h.assertTrue(ledger.boardWagers.open(t.wagerKey(),t.betId),"Unload does not refund or forfeit");t.clearRemoved();h.getLevel().destroyBlock(t.getBlockPos(),false);h.assertTrue(!ledger.boardWagers.open(t.wagerKey(),t.betId)&&f.cash(a)==100&&f.cash(b)==100,"Actual forced block removal refunds");h.succeed();
 }
 @GameTest(maxTicks=60) public void twoPlayersConsentResignAndFreshRematch(GameTestHelper h){var pos=new BlockPos(2,2,2);h.setBlock(pos,BoardGames.CHESS.defaultBlockState());var t=h.getBlockEntity(pos,TableEntity.class);var a=h.makeMockServerPlayerInLevel();var b=h.makeMockServerPlayerInLevel();for(var p:List.of(a,b)){p.setGameMode(net.minecraft.world.level.GameType.SURVIVAL);p.setPos(t.getBlockPos().getX()+1,t.getBlockPos().getY(),t.getBlockPos().getZ());io.github.jimbozoomer.jugcraft.town.Jugs.add(h.getLevel().getServer(),p.getUUID(),100);t.change(p.getUUID(),p.getName().getString(),0,0,0,0);}
  var ledger=Ledger.get(h.getLevel().getServer());var f=ledger.book();t.change(a.getUUID(),"A",8,0,0,0);t.change(a.getUUID(),"A",8,0,0,0);t.change(a.getUUID(),"A",9,0,0,0);h.assertTrue(f.cash(a.getUUID())==100&&t.betId.isEmpty(),"First confirmation does not debit");h.assertTrue(t.change(b.getUUID(),"B",9,0,0,0)&&t.funded()&&t.active(),"Second nearby player starts funded game");h.assertTrue(f.cash(a.getUUID())==95&&f.cash(b.getUUID())==95,"Five Jugs each");
  var saved=t.saveWithFullMetadata(h.getLevel().registryAccess());var restored=new TableEntity(t.getBlockPos(),t.getBlockState());restored.loadWithComponents(net.minecraft.world.level.storage.TagValueInput.create(net.minecraft.util.ProblemReporter.DISCARDING,h.getLevel().registryAccess(),saved));h.assertTrue(restored.betId.equals(t.betId)&&restored.stake==5&&restored.active()&&!restored.agreed[0]&&!restored.agreed[1],"Funded wager identity survives reload while tentative consent does not");
  h.assertTrue(!net.fabricmc.fabric.api.event.player.PlayerBlockBreakEvents.BEFORE.invoker().beforeBlockBreak(h.getLevel(),a,t.getBlockPos(),t.getBlockState(),t),"Cannot break table to avoid loss");
  t.change(b.getUUID(),"B",2,0,0,0);h.assertTrue(f.cash(a.getUUID())==105&&f.cash(b.getUUID())==95,"Resignation pays opponent exactly ten");h.assertTrue(!t.change(b.getUUID(),"B",2,0,0,0)&&f.cash(a.getUUID())==105,"No double payout");t.change(a.getUUID(),"A",5,0,0,0);t.change(b.getUUID(),"B",5,0,0,0);h.assertTrue(t.stake==0&&t.betId.isEmpty()&&!t.agreed[0]&&!t.agreed[1],"Rematch returns to free play and fresh consent");
  t.change(a.getUUID(),"A",8,0,0,0);t.change(a.getUUID(),"A",9,0,0,0);t.change(b.getUUID(),"B",9,0,0,0);t.change(a.getUUID(),"A",3,0,0,0);t.change(b.getUUID(),"B",4,0,0,0);h.assertTrue(f.cash(a.getUUID())==105&&f.cash(b.getUUID())==95,"Agreed draw returns this round's stakes");h.succeed();
 }

}
